@import url('');
:root{color-scheme:dark;--ink:#eef3ec;--muted:#9aa8a6;--teal:#75d8c6;--orange:#f2a66f;--panel:rgba(13,23,27,.88);--line:rgba(220,238,230,.16);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101a20;color:var(--ink);touch-action:none}button{font:inherit;color:inherit}#gameShell{position:relative;width:100%;height:100dvh;min-height:320px;overflow:hidden;background:#152329;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.hidden{display:none!important}.screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center}.menu-screen{background:transparent}.menu-backdrop{position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,15,20,.96) 0%,rgba(9,17,21,.88) 43%,rgba(10,18,22,.20) 100%),linear-gradient(0deg,rgba(9,16,19,.78),transparent 40%),radial-gradient(ellipse at 75% 48%,rgba(89,122,106,.22),transparent 52%);backdrop-filter:blur(1px)}.menu-content{position:relative;width:min(560px,calc(100% - 44px));margin-left:clamp(22px,8vw,150px);margin-right:auto;align-self:center;padding:35px 0 24px}.eyebrow{display:flex;align-items:center;gap:9px;color:#8da39f;font-size:10px;font-weight:800;letter-spacing:2px}.pulse-dot,.live-dot{height:7px;width:7px;border-radius:50%;background:#76e1bc;box-shadow:0 0 14px #76e1bc}.eyebrow-line{width:37px;height:1px;background:rgba(207,227,219,.28);margin:0 5px}.logo-wrap{display:flex;align-items:center;gap:18px;margin:34px 0 22px}.logo-mark{width:53px;height:59px;display:flex;gap:4px;align-items:center;transform:skew(-14deg)}.logo-mark span{display:block;width:13px;background:#d9ede3;clip-path:polygon(0 0,100% 0,100% 78%,0 100%)}.logo-mark span:nth-child(1){height:43px;opacity:.5}.logo-mark span:nth-child(2){height:56px}.logo-mark span:nth-child(3){height:34px;background:var(--teal);clip-path:polygon(0 0,100% 20%,100% 100%,0 100%)}h1{font-size:clamp(46px,7vw,72px);line-height:.88;letter-spacing:4px;margin:0;font-weight:900}h1 span{color:var(--teal);font-weight:500}.logo-wrap p{font-size:9px;letter-spacing:4px;margin:11px 0 0;color:#829593;font-weight:700}.menu-copy{color:#bdc9c4;font-size:17px;line-height:1.55;margin:22px 0 21px}.menu-copy strong{font-size:20px;color:#fff;letter-spacing:.3px}.briefing{max-width:480px;padding:17px 19px 15px;border:1px solid rgba(204,223,215,.15);background:rgba(18,30,34,.68);box-shadow:0 14px 40px rgba(0,0,0,.1)}.briefing-head{display:flex;justify-content:space-between;align-items:center;font-size:9px;font-weight:800;letter-spacing:1.7px;color:#dce7df}.briefing-tag{padding:5px 7px;background:rgba(117,216,198,.1);color:var(--teal);font-size:8px;letter-spacing:1px}.briefing>p{font-size:12px;line-height:1.5;color:#9eafaa;margin:12px 0 15px;max-width:370px}.mission-stats{display:flex;border-top:1px solid rgba(204,223,215,.11);padding-top:12px;gap:0}.mission-stats>div{flex:1;border-right:1px solid rgba(204,223,215,.11);padding-left:12px}.mission-stats>div:first-child{padding-left:0}.mission-stats>div:last-child{border:0}.mission-stats small{display:block;font-size:8px;letter-spacing:1.4px;color:#718580;margin-bottom:5px}.mission-stats b{font-size:9px;letter-spacing:.6px;color:#dbe7e0}.status-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--teal);margin-right:3px}.primary-button{display:flex;width:min(480px,100%);height:54px;margin-top:16px;justify-content:space-between;align-items:center;padding:0 19px 0 22px;background:#a7e7d5;color:#11211f;border:0;cursor:pointer;font-size:11px;font-weight:900;letter-spacing:2px;box-shadow:0 8px 24px rgba(84,203,174,.13);transition:transform .15s,background .15s}.primary-button:hover{background:#c2f6e5;transform:translateY(-2px)}.primary-button b{font-size:20px;font-weight:500}.menu-foot{display:flex;justify-content:space-between;margin-top:18px;max-width:480px;font-size:8px;font-weight:700;letter-spacing:1.15px;color:#60716d}.menu-side-note{position:absolute;right:28px;bottom:25px;font-size:8px;letter-spacing:2px;line-height:1.9;color:rgba(223,239,231,.42);text-align:right}
.hud{position:absolute;z-index:2;left:0;right:0;top:0;height:83px;padding:14px 25px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(8,15,18,.83),rgba(8,15,18,.55) 78%,transparent);pointer-events:none}.hud-brand{display:flex;align-items:center;gap:9px;width:220px}.mini-mark{height:32px;width:30px;display:grid;place-items:center;background:rgba(117,216,198,.13);border:1px solid rgba(117,216,198,.35);color:var(--teal);font-weight:900;font-size:16px;transform:skew(-8deg)}.hud-brand b{font-size:11px;letter-spacing:2px}.hud-brand small{display:block;color:#80918d;font-size:8px;letter-spacing:1.2px;margin-top:3px}.scoreboard{display:flex;align-items:center;gap:21px;padding:6px 21px;background:rgba(12,21,24,.75);border:1px solid rgba(222,239,232,.12);min-width:210px;justify-content:center}.team-score{display:flex;align-items:center;gap:9px;font-size:23px;font-weight:800;min-width:36px}.team-score i{height:7px;width:7px;background:#70d9c5;display:block;transform:rotate(45deg)}.red-score i{background:#ee916d}.round-label{text-align:center;border-left:1px solid var(--line);border-right:1px solid var(--line);padding:0 14px}.round-label small{display:block;font-size:7px;color:#83928e;letter-spacing:1.7px}.round-label b{font-size:13px;letter-spacing:1px}.red-score{color:#eab197}.hud-status{width:220px;display:flex;align-items:center;justify-content:flex-end;gap:8px;color:#adbfba;font-size:9px;letter-spacing:.8px}.live-dot{width:6px;height:6px}.status-divider{height:12px;width:1px;background:var(--line);margin:0 3px}.hud-status #roundClock{font-variant-numeric:tabular-nums;font-weight:800;color:#e0e9e3;letter-spacing:1px}.player-panel{position:absolute;z-index:2;left:25px;bottom:24px;width:210px;padding:12px 14px;background:linear-gradient(100deg,rgba(10,20,23,.9),rgba(12,23,27,.65));border:1px solid rgba(220,238,230,.13);clip-path:polygon(0 0,100% 0,100% calc(100% - 11px),calc(100% - 11px) 100%,0 100%);pointer-events:none}.health-row{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:1.6px;color:#aab9b4}.health-row b{font-size:15px;letter-spacing:0;color:#e6eee8}.health-track{height:4px;margin:6px 0 10px;background:rgba(230,239,234,.15)}.health-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#6dd9bd,#b4e6b5);transition:width .2s}.weapon-row{display:flex;align-items:center;border-top:1px solid rgba(220,238,230,.1);padding-top:9px}.weapon-icon{font-size:25px;color:var(--teal);width:29px;transform:rotate(-25deg)}.weapon-name{display:flex;flex-direction:column;gap:4px}.weapon-name b{font-size:9px;letter-spacing:1px}.weapon-name small{font-size:7px;letter-spacing:1px;color:#778984}.ammo{margin-left:auto;display:flex;align-items:baseline;gap:4px}.ammo b{font-size:19px;font-weight:800}.ammo span,.ammo small{color:#889691;font-size:10px}.squad-panel{position:absolute;z-index:2;right:24px;bottom:25px;width:176px;padding:10px 12px;background:rgba(11,21,24,.77);border:1px solid rgba(220,238,230,.12);pointer-events:none}.squad-label{display:flex;justify-content:space-between;font-size:8px;font-weight:800;letter-spacing:1.2px;color:#c3d0c9}.squad-label span{font-size:7px;color:#71cbb8}.squad-pips{display:flex;gap:5px;margin-top:9px}.squad-pip{flex:1;height:5px;background:#71d7c0;transition:opacity .2s}.squad-pip.dead{background:#687571;opacity:.35}.objective-hint{position:absolute;z-index:2;left:50%;bottom:27px;transform:translateX(-50%);display:flex;align-items:center;gap:9px;padding:9px 13px;background:rgba(12,22,25,.75);border:1px solid rgba(220,238,230,.13);pointer-events:none}.objective-icon{font-size:18px;color:var(--orange)}.objective-hint b{display:block;font-size:8px;letter-spacing:1.3px}.objective-hint small{display:block;font-size:7px;color:#93a39d;margin-top:3px;letter-spacing:1px}.kill-feed{position:absolute;z-index:2;right:25px;top:94px;display:flex;flex-direction:column;align-items:flex-end;gap:5px;pointer-events:none}.feed-item{font-size:9px;letter-spacing:.3px;padding:7px 10px;background:rgba(12,22,25,.7);border-right:2px solid var(--teal);color:#e2ece5;animation:feed-in .2s ease-out}.feed-item.enemy{border-color:var(--orange)}@keyframes feed-in{from{transform:translateX(12px);opacity:0}to{transform:none;opacity:1}}.toast{position:absolute;z-index:3;top:25%;left:50%;transform:translate(-50%,-10px);padding:9px 15px;background:rgba(12,22,25,.9);border:1px solid rgba(117,216,198,.3);font-size:9px;letter-spacing:1.2px;color:#dff5e9;opacity:0;transition:opacity .2s,transform .2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.reticle{position:absolute;z-index:3;left:50%;top:50%;width:25px;height:25px;transform:translate(-50%,-50%);pointer-events:none;transition:opacity .1s}.reticle i{position:absolute;background:rgba(237,246,236,.9);box-shadow:0 0 3px #162522}.reticle i:nth-child(1){width:2px;height:6px;left:11px;top:0}.reticle i:nth-child(2){width:2px;height:6px;left:11px;bottom:0}.reticle i:nth-child(3){width:6px;height:2px;left:0;top:11px}.reticle i:nth-child(4){width:6px;height:2px;right:0;top:11px}.reticle b{position:absolute;inset:10px;border:1px solid rgba(117,216,198,.9);border-radius:50%}.hit-marker{position:absolute;z-index:4;left:50%;top:50%;transform:translate(-50%,-50%);color:#f4d18e;font-size:34px;font-weight:300;pointer-events:none;text-shadow:0 1px 5px #000}.controls{position:absolute;z-index:4;left:0;right:0;bottom:0;height:190px;pointer-events:none}.move-pad{position:absolute;left:22px;bottom:21px;width:132px;height:132px;pointer-events:auto;touch-action:none}.pad-ring{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(222,240,229,.32);background:rgba(17,30,32,.36);box-shadow:inset 0 0 30px rgba(190,225,211,.07)}.pad-knob{position:absolute;left:50%;top:50%;width:54px;height:54px;border-radius:50%;transform:translate(-50%,-50%);border:1px solid rgba(222,240,229,.55);background:rgba(201,232,218,.22);box-shadow:0 3px 14px rgba(0,0,0,.2)}.pad-label{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:7px;font-weight:800;letter-spacing:1px;color:rgba(237,246,236,.5);pointer-events:none}.touch-actions{position:absolute;right:23px;bottom:20px;display:flex;align-items:flex-end;gap:14px;pointer-events:auto}.fire-button{width:90px;height:90px;border-radius:50%;border:1px solid rgba(244,178,132,.72);background:rgba(184,95,61,.38);box-shadow:inset 0 0 0 7px rgba(244,178,132,.08),0 6px 20px rgba(0,0,0,.2);display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px;touch-action:none}.fire-button:active{background:rgba(220,126,78,.68);transform:scale(.97)}.fire-cross{font-size:24px;line-height:1;color:#ffd2af}.fire-button b{font-size:8px;letter-spacing:1.5px}.action-button{width:58px;height:58px;border-radius:50%;border:1px solid rgba(218,237,226,.36);background:rgba(14,26,29,.62);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;touch-action:none}.action-button span{font-size:22px;color:#d8e6de;line-height:1}.action-button small{font-size:6px;letter-spacing:.8px;color:#c0cec7}.round-screen,.pause-screen{background:rgba(8,15,18,.57);backdrop-filter:blur(6px)}.round-card{width:min(440px,calc(100% - 42px));padding:33px 35px;background:rgba(15,26,29,.97);border:1px solid rgba(213,234,222,.17);box-shadow:0 25px 90px rgba(0,0,0,.48);text-align:center}.round-card .eyebrow{justify-content:center}.round-card h2{margin:13px 0 7px;font-size:33px;letter-spacing:1px}.round-card>p{margin:0;color:#99aaa3;font-size:13px}.round-result{display:flex;align-items:center;justify-content:space-between;margin:23px 0 7px;padding:12px 15px;background:rgba(219,237,225,.05);font-size:9px;letter-spacing:1.5px;color:#91aaa2}.round-result b{font-size:18px;letter-spacing:1px;color:#e6eee8}.round-card .primary-button{width:100%}.text-button{margin-top:17px;border:0;background:none;color:#80938c;font-size:9px;letter-spacing:1.3px;cursor:pointer}.pause-button{position:absolute;z-index:3;top:91px;right:24px;width:32px;height:32px;border:1px solid rgba(225,240,232,.28);background:rgba(12,22,25,.6);color:#dbe9df;font-size:12px;cursor:pointer}.desktop-help{position:absolute;z-index:2;bottom:17px;left:50%;transform:translateX(-50%);font-size:8px;color:#dce8df;letter-spacing:1px;opacity:.7;white-space:nowrap;pointer-events:none}.desktop-help span{color:#a7b6af;margin-left:4px;margin-right:10px}.desktop-help i{display:inline-block;height:10px;width:1px;background:rgba(220,238,230,.25);vertical-align:middle;margin:0 8px}.orientation-hint{display:none}
@media (pointer:fine){.controls{display:none!important}}@media(max-width:700px){.menu-content{margin-left:24px;width:min(485px,calc(100% - 48px));padding-top:19px}.logo-wrap{margin:23px 0 17px}.logo-mark{transform:scale(.85) skew(-14deg);transform-origin:left center;width:45px}h1{font-size:50px}.menu-copy{font-size:14px;margin:17px 0}.menu-copy strong{font-size:17px}.briefing{padding:14px 15px 13px}.briefing>p{font-size:11px;margin:9px 0 12px}.mission-stats b{font-size:8px}.primary-button{height:48px}.menu-foot{margin-top:12px}.menu-side-note{display:none}.hud{height:70px;padding:11px 14px}.hud-brand{width:auto}.hud-brand b{font-size:9px}.hud-brand small{font-size:7px}.mini-mark{width:26px;height:28px}.scoreboard{min-width:auto;gap:10px;padding:5px 11px}.team-score{font-size:18px;gap:6px}.round-label{padding:0 8px}.hud-status{width:auto;font-size:8px;gap:5px}.player-panel{left:13px;bottom:13px;transform:scale(.84);transform-origin:bottom left}.squad-panel{right:12px;bottom:13px;transform:scale(.85);transform-origin:bottom right}.objective-hint{bottom:14px;transform:translateX(-50%) scale(.9)}.kill-feed{right:12px;top:78px}.pause-button{top:76px;right:13px}.desktop-help{display:none!important}}
@media(max-width:540px){.hud-brand small{display:none}.hud-brand{gap:6px}.hud-brand b{letter-spacing:1px}.hud-status #matchStatus,.status-divider{display:none}.scoreboard{gap:7px;padding:4px 8px}.team-score{font-size:16px}.round-label{padding:0 6px}.round-label small{font-size:6px}.round-label b{font-size:11px}.hud-status{font-size:8px}.player-panel{bottom:152px;transform:scale(.76)}.squad-panel{bottom:152px;transform:scale(.76)}.objective-hint{bottom:142px;transform:translateX(-50%) scale(.8)}.controls{height:164px}.move-pad{width:118px;height:118px;left:15px;bottom:18px}.pad-knob{width:48px;height:48px}.touch-actions{right:15px;bottom:17px;gap:10px}.fire-button{width:78px;height:78px}.action-button{width:49px;height:49px}.round-card{padding:27px 24px}.round-card h2{font-size:28px}}
@media(orientation:portrait) and (max-width:700px){.orientation-hint{position:absolute;z-index:10;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;background:#101a20;color:#eaf2eb;text-align:center}.rotate-icon{font-size:38px;color:var(--teal);transform:rotate(45deg);margin-bottom:8px}.orientation-hint b{font-size:11px;letter-spacing:2px}.orientation-hint small{font-size:11px;color:#94a69f}#menuScreen,#hud,#playerPanel,#squadPanel,#objectiveHint,#controls,#pauseButton,#desktopHelp{visibility:hidden}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = {
    menu: $('menuScreen'), hud: $('hud'), playerPanel: $('playerPanel'), squadPanel: $('squadPanel'),
    objective: $('objectiveHint'), controls: $('controls'), roundScreen: $('roundScreen'), pauseScreen: $('pauseScreen'),
    pauseButton: $('pauseButton'), help: $('desktopHelp'), reticle: $('reticle'), toast: $('toast'),
    blueScore: $('blueScore'), redScore: $('redScore'), roundNumber: $('roundNumber'), clock: $('roundClock'),
    status: $('matchStatus'), health: $('healthValue'), healthBar: $('healthBar'), clip: $('ammoClip'), reserve: $('ammoReserve'),
    pips: $('squadPips'), feed: $('killFeed'), hit: $('hitMarker'), roundTitle: $('roundTitle'),
    roundCopy: $('roundCopy'), roundKicker: $('roundKicker'), resultScore: $('resultScore'), continue: $('continueButton')
  };
  const WORLD = { w: 1900, h: 1220 };
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
  const rand = (a, b) => a + Math.random() * (b - a);
  const obstacles = [
    {x:0,y:0,w:WORLD.w,h:34,kind:'wall'}, {x:0,y:WORLD.h-34,w:WORLD.w,h:34,kind:'wall'},
    {x:0,y:0,w:34,h:WORLD.h,kind:'wall'}, {x:WORLD.w-34,y:0,w:34,h:WORLD.h,kind:'wall'},
    {x:755,y:265,w:330,h:76,kind:'container',label:'CARGO 04'},
    {x:815,y:341,w:78,h:170,kind:'container',label:'04'},
    {x:1040,y:650,w:338,h:78,kind:'container',label:'CARGO 12'},
    {x:1299,y:728,w:79,h:190,kind:'container',label:'12'},
    {x:398,y:360,w:166,h:67,kind:'crate'}, {x:508,y:430,w:70,h:135,kind:'crate'},
    {x:1360,y:355,w:160,h:66,kind:'crate'}, {x:1285,y:427,w:70,h:115,kind:'crate'},
    {x:431,y:807,w:215,h:77,kind:'wall'}, {x:645,y:807,w:68,h:170,kind:'wall'},
    {x:1494,y:808,w:206,h:76,kind:'wall'}, {x:1494,y:694,w:76,h:115,kind:'wall'},
    {x:875,y:868,w:168,h:66,kind:'crate'}, {x:1060,y:358,w:128,h:60,kind:'crate'},
    {x:736,y:616,w:90,h:70,kind:'crate'}, {x:823,y:616,w:59,h:122,kind:'crate'},
    {x:1210,y:495,w:130,h:61,kind:'crate'}, {x:1238,y:958,w:160,h:67,kind:'crate'},
    {x:310,y:596,w:150,h:62,kind:'crate'}, {x:1580,y:553,w:130,h:65,kind:'crate'},
    {x:921,y:135,w:82,h:66,kind:'crate'}, {x:935,y:1020,w:92,h:66,kind:'crate'}
  ];
  let W = 0, H = 0, dpr = 1, last = 0, state = 'menu', player = null, units = [], bullets = [], particles = [];
  let scoreBlue = 0, scoreRed = 0, round = 1, roundTime = 120, camera = {x:950,y:610}, mouse = {x:0,y:0,down:false}, moveInput = {x:0,y:0};
  let fireHeld = false, reloadUntil = 0, toastTimer = 0, hitTimer = 0, shake = 0, elapsed = 0, cinematic = 0;
  const isTouch = matchMedia('(pointer: coarse)').matches;
  const botsAlive = (team) => units.filter(u => u.team === team && !u.dead).length;

  function resize(){
    const rect = canvas.getBoundingClientRect(); W = rect.width; H = rect.height; dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(W*dpr); canvas.height = Math.round(H*dpr); ctx.setTransform(dpr,0,0,dpr,0,0);
  }
  window.addEventListener('resize', resize); resize();
  function freshUnit(team, x, y, isPlayer=false, name=''){
    return {team,x,y,angle:team==='blue'?0:Math.PI,hp:100,maxHp:100,dead:false,isPlayer,name,
      radius:isPlayer?18:16,speed:isPlayer?222:(team==='blue'?144:137),cool:rand(.2,.8),flash:0,spawnX:x,spawnY:y,
      strafe:Math.random()<.5?-1:1,think:0,moveX:0,moveY:0};
  }
  function resetRound(){
    units=[]; bullets=[]; particles=[];
    player=freshUnit('blue',220,970,true,'YOU'); units.push(player);
    units.push(freshUnit('blue',315,865,false,'MICA')); units.push(freshUnit('blue',430,1010,false,'ROOK'));
    units.push(freshUnit('red',1650,245,false,'VEX')); units.push(freshUnit('red',1510,330,false,'KITE')); units.push(freshUnit('red',1710,420,false,'ASH'));
    roundTime=120; reloadUntil=0; fireHeld=false; moveInput={x:0,y:0};
    updateHUD();
  }
  function deploy(){scoreBlue=0;scoreRed=0;round=1;state='playing';ui.menu.classList.add('hidden');ui.roundScreen.classList.add('hidden');ui.pauseScreen.classList.add('hidden');
    ui.hud.classList.remove('hidden');ui.playerPanel.classList.remove('hidden');ui.squadPanel.classList.remove('hidden');ui.objective.classList.remove('hidden');ui.pauseButton.classList.remove('hidden');
    ui.controls.classList.toggle('hidden',!isTouch);ui.help.classList.toggle('hidden',isTouch);ui.reticle.classList.toggle('hidden',isTouch);ui.status.textContent='LIVE ENGAGEMENT';resetRound();last=performance.now();}
  $('startButton').addEventListener('click',deploy);
  $('continueButton').addEventListener('click',()=>{
    ui.roundScreen.classList.add('hidden');
    if(scoreBlue>=3||scoreRed>=3){state='menu';ui.menu.classList.remove('hidden');ui.hud.classList.add('hidden');ui.playerPanel.classList.add('hidden');ui.squadPanel.classList.add('hidden');ui.objective.classList.add('hidden');ui.pauseButton.classList.add('hidden');ui.controls.classList.add('hidden');ui.help.classList.add('hidden');return;}
    round++;state='playing';ui.status.textContent='LIVE ENGAGEMENT';resetRound();last=performance.now();
  });
  $('pauseButton').addEventListener('click',pause); $('resumeButton').addEventListener('click',resume);
